package server

// The descriptions of the five file tools and the server instructions are unchanged from the TypeScript server; clients truncate any over 2048
// characters, which a test checks.

const toolInstructions = "Hashline file tools; use them to list, read, search, edit and write text files, instead of the built-in Read, Grep, Glob, Edit and Write and instead of cat, head, sed, grep, find, ls, wc, cp or heredocs in the shell (built-in Read stays for PDFs and notebooks).\nread and grep print a [PATH#TAG] header (TAG: 4-hex snapshot of the whole file) and LINE:TEXT rows. edit addresses those line numbers, so never repeat old text.\nSave calls and tokens: grep for a name instead of reading a whole file; read several files and ranges in one read; edit straight from grep rows; put every change, across files, into one edit call; after an edit or write, use the new tag and rows from its response instead of re-reading."

// EditDescription is the edit tool description.
const EditDescription = "Apply a hashline patch to one or more files. Numbers refer to the [PATH#TAG] output of your latest read, grep, write or edit of that file.\n\n[PATH#TAG]\nPUT N.=M:   replace lines N..M (PUT N: for one) with the + rows below\nPUT N*:     replace the block starting at N (doc comment, decorators, body, closing line)\nPUT <N:     insert + rows before line N\nPUT >N:     insert + rows after line N\nPUT >N*:    insert + rows after the block starting at N\nPUT >$:     append + rows at end of file ([PATH] with no #TAG allows only this)\nCUT N.=M    delete lines N..M (CUT N for one)\nCUT N*      delete the block starting at N\nSUB N: OLD  replace text OLD (once on line N) with the + rows; a lone + deletes it\nREM         delete the file (only op in its section)\nMV DEST     move the file, after the section's edits\nCP DEST     like MV, but the file itself stays as it was\n*** Add File: PATH\n+content    new file; missing parents are created\n\nRules:\n- Copy [PATH#TAG] exactly; one section per file. Body rows are + then the exact line, indent included; a lone + is a blank line. Never write - rows, context rows or LINE: prefixes.\n- Every number in a section refers to that same output, never shifted by earlier hunks. Hunks must not overlap. Keep ranges tight; split distant changes into separate hunks.\n- For a whole function, class or statement block use N* at its first line instead of counting to its end.\n- Anchor lines shown as N:TEXT (grep context too) or N~TEXT. A ~TEXT row under PUT or CUT checks that line N starts with TEXT (a second ~ checks line M); checked, inserts may use any line and replaces any line you wrote or saw.\n- The response has a new [PATH#TAG], a kept row on each side of a change, your new rows and notes for moved lines: use them next. An older tag keeps its numbers: unchanged lines are rebased (with a warning), others rejected with current content.\n\nExample, for [src/a.ts#3C4D] showing 1:const a = 1 2:const b = 2 3:export { a }:\n[src/a.ts#3C4D]\nPUT 2.=2:\n+const b = 3\nPUT >3:\n+export { b }"

const readDescription = "Read text files as a [PATH#TAG] header plus LINE:TEXT rows, list directories, or view images. Pass every file you need in one call. A path may end in a line selector: path:A, path:A-B, path:A+COUNT, path:A- (to the end), path:-N (last N) or path:A-B,C-D, or a declared name, path:Class.method (overloads too; in a template a block or snippet), for its lines and doc comment. path#TAG, a tag from an earlier read or edit, shows only what changed since (+N: added rows, -| removed ones). path@REV: the file at a git commit, or a folder's commit and diff. Without a selector, a large file returns an outline of its declarations, or for flat data its first 100 lines; read a declaration by name, or grep. Lockfiles, minified files and node_modules/ or dist/ are skipped without a range. One call shares a 40 KiB output budget. Rows cut at maxLineLength or holding color codes are bracketed and are not anchors; edit them with SUB. Unchanged lines you saw may print as one [lines A-B ...] row; they stay anchors."

const grepDescription = "Search file contents with ripgrep (Rust regex; .gitignore respected, hidden files included). Matches are grouped per file under [PATH#TAG] headers as *LINE:TEXT rows with LINE:TEXT context rows, all edit anchors. 20 files per page, 20 matches per file (100 for a single file, all with replace). Files over 2 MiB or still growing give N|TEXT rows, which are not anchors. replace previews each changed line as a >N| row and returns a token; edit with REAPPLY TOKEN applies exactly those changes."

const findDescription = "List files recursively, like find or fd (.gitignore respected, hidden files included). Each row gives the path with its line count, size and age, like src/app.ts (120 lines, 3.4 KiB, 2h ago). Paths continue the head's under DIR/, if any; a DIR/ row's files follow it, indented, with their path below DIR/. 200 files per page."

const writeDescription = "Write a whole file, creating missing parent directories; overwriting an existing file needs the tag of its latest read or edit. Prefer edit for partial changes. The response maps the file with N~TEXT rows that edit can anchor on."
